const r = $('Resolve Identity').first().json;
const c = r.customer, m = r.message;

const kb = $input.all().map(i => i.json).filter(k => k.topic && k.content)
  .map(k => '- ' + k.topic + ': ' + k.content).join('\n') || '- (no knowledge base entries found)';
const v = x => (x === undefined || x === null || String(x).trim() === '') ? 'unknown' : x;

const systemPrompt = `You are "Haven Assistant", the AI assistant of Haven Real Estates (residential sales and rentals). Customers reach you on three channels - website chat, email and Discord - but you are ONE assistant with ONE shared customer record, ONE memory and ONE set of business rules. Never behave like a different bot per channel.

TODAY: ${new Date().toDateString()}
CURRENT CHANNEL: ${m.channel}
RETURNING CUSTOMER: ${r.is_new ? 'no (new profile just created)' : 'yes (recognised via ' + r.matched_by + ')'}

SHARED CUSTOMER RECORD (same on every channel):
- customer_id: ${c.customer_id}
- name: ${v(c.name)}
- email: ${c.email ? 'on file' : 'missing'} | phone: ${c.phone ? 'on file' : 'missing'} | discord: ${c.discord_id ? 'linked' : 'not linked'}
- channels used so far: ${v(c.channels_used)}
- transaction_type (buy/rent/sell): ${v(c.transaction_type)}
- property_type: ${v(c.property_type)} | bedrooms: ${v(c.bedrooms)}
- budget: ${v(c.budget)}
- preferred_neighborhoods: ${v(c.preferred_neighborhoods)}
- timeline: ${v(c.timeline)}
- financing_status: ${v(c.financing_status)}
- lead_status: ${v(c.lead_status)} | lead_score: ${v(c.lead_score)}
- interested_listings: ${v(c.interested_listings)}
- assigned_broker: ${v(c.assigned_broker)}
- running summary: ${v(c.conversation_summary)}

KNOWLEDGE BASE (your only source of company facts - do not invent policies):
${kb}

YOUR TOOL
- "Search Listings": returns every row of the Listings sheet. Call it whenever the customer states or changes preferences, or asks about availability or prices. Only recommend rows with status "Available" and a listing_type that matches the need (Sale = buying, Rent = renting). Never invent listings, prices, addresses or image links.

GOALS
1. Understand the request: buy, rent, sell, viewing, general info, complaint.
2. Qualify the lead naturally with at most 1-2 questions per message. Collect: transaction type, budget, preferred neighborhoods, property type / bedrooms, timeline, financing readiness (buying: pre-approved, cash, needs mortgage help, not sure; renting: ready to apply, needs more time). Never re-ask what is already in the record or in this conversation.
3. Once you know enough preferences, call Search Listings and present up to 3 best matches. For each: title, neighborhood, price, bedrooms/bathrooms, one or two key features, the listing_id, and the image_url alone on its own line. Then ask which one they like.
4. If nothing matches, say so honestly and offer the closest alternatives or ask to adjust budget or area.
5. If email AND phone are both missing, politely ask once for an email or phone number so the conversation can continue on any channel. Do not repeat if they decline.
6. Hand off to a human broker (handoff_to_broker = true) when: the customer is interested in a specific listing AND budget, neighborhoods, timeline and financing readiness are all known (from the record or this message); OR they ask to speak with a person; OR they ask about commission, legal or tax matters; OR they make a complaint; OR they are ready to make an offer. If a core qualification item is missing, ask for it before handing off. When handing off, tell the customer a broker will contact them within one business day on their preferred channel.

STYLE
- website: short and friendly. discord: concise, light formatting allowed. email: slightly longer, with greeting and sign-off "Haven Real Estates Team".
- Reply in the language the customer writes in.
- Personalise using the record and conversation memory, but never reveal other people's data and never read back full email addresses or phone numbers.
- Never promise discounts, quote commission, give legal/tax/financial advice, or guarantee availability - a broker confirms everything.

OUTPUT FORMAT - return ONLY one valid JSON object, no markdown fences, no text outside it:
{
  "reply": "text sent to the customer. Use \\n for line breaks. Put each image URL alone on its own line.",
  "intent": "buy | rent | sell | viewing | info | complaint | other",
  "customer_interested": true | false | null,
  "human_requested": true | false,
  "handoff_to_broker": true | false,
  "interested_listing_ids": ["listing_ids the customer actually showed interest in - not merely listings you showed"],
  "profile_updates": {
    "name": null, "email": null, "phone": null, "transaction_type": null, "property_type": null,
    "budget": null, "preferred_neighborhoods": null, "bedrooms": null, "timeline": null, "financing_status": null
  },
  "conversation_summary": "2-3 sentence running summary of the customer's needs and status, merging the previous summary with this message"
}
Use null for anything not learned in this message. In profile_updates put only facts the customer stated.`;

const chatInput = '[Channel: ' + m.channel + (m.subject ? ' | Email subject: ' + m.subject : '') + ']\n' + m.message;
return [{ json: { systemPrompt, chatInput, customer: c, message: m } }];

const ctx = $('Build Agent Context').first().json;
const c = { ...ctx.customer };
const m = ctx.message;
const now = new Date().toISOString();

// ---- 1. parse Gemini's JSON (tolerate code fences / stray text) ----
let raw = $input.first().json.output;
if (raw && typeof raw === 'object') raw = JSON.stringify(raw);
raw = (raw || '').toString();
let p;
try {
  const cleaned = raw.replace(/```json|```/gi, '').trim();
  p = JSON.parse(cleaned.slice(cleaned.indexOf('{'), cleaned.lastIndexOf('}') + 1));
} catch (e) {
  p = { reply: raw.trim() || 'Thanks for your message! A member of the Haven team will get back to you shortly.', intent: 'other', profile_updates: {} };
}

// ---- 2. apply profile updates (email/phone only fill blanks) ----
const up = p.profile_updates || {};
const fields = ['name','email','phone','transaction_type','property_type','budget','preferred_neighborhoods','bedrooms','timeline','financing_status'];
for (const f of fields) {
  let val = up[f];
  if (Array.isArray(val)) val = val.join(', ');
  if (val === null || val === undefined || String(val).trim() === '' || /^unknown$/i.test(String(val))) continue;
  if ((f === 'email' || f === 'phone') && String(c[f] || '').trim() !== '') continue;
  c[f] = String(val).trim();
}
if (c.email) c.email = c.email.toLowerCase();

const ids = (Array.isArray(p.interested_listing_ids) ? p.interested_listing_ids : []).map(String);
if (ids.length) {
  const s = new Set(String(c.interested_listings || '').split(',').map(x => x.trim()).filter(Boolean));
  ids.forEach(i => s.add(i));
  c.interested_listings = [...s].join(', ');
}
if (p.conversation_summary) c.conversation_summary = String(p.conversation_summary).slice(0, 600);

// ---- 3. central business logic: scoring, status, handoff ----
const core = ['budget', 'preferred_neighborhoods', 'timeline', 'financing_status'];
const known = core.filter(f => String(c[f] || '').trim() !== '').length;
const interested = p.customer_interested === true || String(c.interested_listings || '').trim() !== '';
const score = Math.min(100, known * 20 + (String(c.transaction_type || '').trim() ? 10 : 0) + (interested ? 10 : 0));

const prevStatus = String(ctx.customer.lead_status || 'New');
const alreadyHot = /^Hot/i.test(prevStatus);
const reachable = c.email || c.phone || c.discord_id;
let handoff = (p.handoff_to_broker === true && !alreadyHot) || p.human_requested === true;

let status = prevStatus;
if (handoff) status = 'Hot Lead - Broker Handoff';
else if (!alreadyHot) status = known >= 3 ? 'Warm' : (known >= 1 ? 'Qualifying' : 'New');
if (handoff && !c.assigned_broker) c.assigned_broker = 'Pending - Human Broker';
c.lead_status = status;
c.lead_score = score;

// ---- 4. format the reply for each channel ----
let reply = (p.reply || '').toString().trim() || 'Thanks for reaching out to Haven Real Estates! How can I help you today?';
if (handoff && !reachable) reply += '\n\nSo our broker can reach you, please share your email address or phone number.';
const imgRe = /https?:\/\/[^\s)<>"']+\.(?:png|jpe?g|webp|gif)(?:\?[^\s)<>"']*)?/gi;
const images = [...new Set(reply.match(imgRe) || [])];
const replyWebsite = reply.replace(imgRe, '').replace(/\n{3,}/g, '\n\n').trim();

const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const toHtml = text => text.split('\n').map(line => esc(line).replace(/https?:\/\/[^\s<]+/g, u => {
  const clean = u.replace(/[.,;)]+$/, ''), tail = u.slice(clean.length);
  return (/\.(png|jpe?g|webp|gif)(\?|$)/i.test(clean)
    ? '<br><img src="' + clean + '" width="480" style="max-width:100%;border-radius:8px;margin:6px 0"><br>'
    : '<a href="' + clean + '">' + clean + '</a>') + tail;
})).join('<br>');
const replyHtml = '<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.5">' + toHtml(reply) + '</div>';

const contact = c.email || c.phone || (c.discord_id ? 'Discord ID ' + c.discord_id : 'Not provided (website session ' + (c.web_session_id || 'unknown') + ')');
const brokerSubject = '[Haven Broker Alert] Hot lead: ' + (c.name || c.customer_id) + ' (' + score + '/100)';
const brokerHtml = '<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.6">'
  + '<h3>New qualified lead for Haven Real Estates</h3>'
  + '<table cellpadding="4">'
  + '<tr><td><b>Customer</b></td><td>' + esc(c.name || '(name not given)') + ' (' + c.customer_id + ')</td></tr>'
  + '<tr><td><b>Contact</b></td><td>' + esc(String(contact)) + '</td></tr>'
  + '<tr><td><b>Channels used</b></td><td>' + esc(c.channels_used) + ' (latest: ' + m.channel + ')</td></tr>'
  + '<tr><td><b>Wants</b></td><td>' + esc(c.transaction_type || '-') + ', ' + esc(c.property_type || '-') + ', ' + esc(String(c.bedrooms || '-')) + ' bed</td></tr>'
  + '<tr><td><b>Budget</b></td><td>' + esc(String(c.budget || '-')) + '</td></tr>'
  + '<tr><td><b>Neighborhoods</b></td><td>' + esc(c.preferred_neighborhoods || '-') + '</td></tr>'
  + '<tr><td><b>Timeline</b></td><td>' + esc(c.timeline || '-') + '</td></tr>'
  + '<tr><td><b>Financing</b></td><td>' + esc(c.financing_status || '-') + '</td></tr>'
  + '<tr><td><b>Interested in</b></td><td>' + esc(c.interested_listings || '-') + '</td></tr>'
  + '<tr><td><b>Lead score</b></td><td>' + score + '/100</td></tr>'
  + '<tr><td><b>Summary</b></td><td>' + esc(c.conversation_summary || '-') + '</td></tr>'
  + '<tr><td><b>Last message</b></td><td>' + esc(m.message) + '</td></tr></table></div>';

const subject = m.subject ? (/^re:/i.test(m.subject) ? m.subject : 'Re: ' + m.subject) : 'Re: Your Haven Real Estates enquiry';

return [{ json: {
  customer_id: c.customer_id,
  channel: m.channel,
  reply,
  reply_website: replyWebsite,
  reply_html: replyHtml,
  images,
  subject,
  reply_ref: m.reply_ref,
  email_message_id: m.email_message_id,
  intent: p.intent || 'other',
  profile: c,
  handoff,
  broker_subject: brokerSubject,
  broker_html: brokerHtml,
  conversation: { timestamp: now, customer_id: c.customer_id, channel: m.channel, customer_message: m.message, ai_reply: reply, intent: p.intent || 'other', lead_status: status },
  handoff_row: { timestamp: now, customer_id: c.customer_id, name: c.name || '', contact: String(contact), channel: m.channel, lead_score: score,
    budget: c.budget || '', preferred_neighborhoods: c.preferred_neighborhoods || '', timeline: c.timeline || '', financing_status: c.financing_status || '',
    interested_listings: c.interested_listings || '', summary: c.conversation_summary || '', status: 'Pending' }
}}];

const b = $input.first().json.body || {};
const text = (b.message || '').toString().trim() || '(customer opened the chat without typing a message)';
return [{ json: {
  channel: 'website',
  message: text.slice(0, 4000),
  name: (b.name || '').toString().trim(),
  email: (b.email || '').toString().trim().toLowerCase(),
  phone: (b.phone || '').toString().trim(),
  discord_id: '',
  subject: '',
  reply_ref: (b.session_id || '').toString(),
  email_message_id: '',
  received_at: new Date().toISOString()
}}];

const out = [];
for (const it of $input.all()) {
  const j = it.json;
  let addr = '', name = '';
  if (j.from && j.from.value && j.from.value[0]) {
    addr = j.from.value[0].address || '';
    name = j.from.value[0].name || '';
  } else if (typeof j.From === 'string') {
    const m = j.From.match(/^(.*?)<([^>]+)>/);
    if (m) { name = m[1].replace(/["']/g, '').trim(); addr = m[2]; } else { addr = j.From.trim(); }
  }
  addr = addr.toLowerCase();
  const subject = j.subject || j.Subject || '';
  // ignore automated mail and our own broker alerts (prevents loops)
  if (!addr || /no-?reply|mailer-daemon|notifications?@/.test(addr)) continue;
  if (/^\[Haven Broker Alert\]/i.test(subject)) continue;
  let body = (j.text || j.textPlain || j.snippet || '').toString();
  body = body.split(/\r?\nOn .{0,120}wrote:/)[0].split(/\r?\n>/)[0].trim();   // drop quoted history
  if (!body) continue;
  out.push({ json: {
    channel: 'email',
    message: body.slice(0, 4000),
    name, email: addr, phone: '', discord_id: '',
    subject,
    reply_ref: j.threadId || '',
    email_message_id: j.id || '',
    received_at: new Date().toISOString()
  }});
}
return out;

const b = $input.first().json.body || {};
const text = (b.message || '').toString().trim() || '(empty Discord message)';
return [{ json: {
  channel: 'discord',
  message: text.slice(0, 4000),
  name: (b.username || '').toString().trim(),
  email: '',
  phone: '',
  discord_id: (b.discord_id || '').toString().trim(),
  subject: '',
  reply_ref: (b.channel_id || '').toString(),
  email_message_id: (b.message_id || '').toString(),
  received_at: new Date().toISOString()
}}];

// ---- Unified identity resolution WITH duplicate merging (replaces the code in the "Resolve Identity" node) ----
const msg = $('Unified Message').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.customer_id);

const normEmail = e => (e || '').toString().trim().toLowerCase();
const normPhone = p => { const d = (p || '').toString().replace(/\D/g, ''); return d.length >= 7 ? d.slice(-10) : ''; };
const same = (a, b) => String(a || '').trim() !== '' && String(a).trim() === String(b || '').trim();

// contact details typed inside the message ("my email is ...")
const emailInText = (msg.message.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/) || [])[0] || '';
const phoneInText = (msg.message.match(/\+?\d[\d\s().-]{8,}\d/g) || [])
  .find(p => { const n = p.replace(/\D/g, ''); return n.length >= 10 && n.length <= 15; }) || '';

const incoming = {
  email: normEmail(msg.email || emailInText),
  phone: (msg.phone || phoneInText || '').toString().trim(),
  discord_id: (msg.discord_id || '').toString().trim(),
  web_session_id: msg.channel === 'website' ? (msg.reply_ref || '') : ''
};

// ---- find EVERY row that belongs to this person (any identifier), ignoring rows already merged ----
const isMatch = r =>
  (incoming.email && normEmail(r.email) === incoming.email) ||
  (normPhone(incoming.phone) && normPhone(r.phone) === normPhone(incoming.phone)) ||
  (incoming.discord_id && same(r.discord_id, incoming.discord_id)) ||
  (incoming.web_session_id && same(r.web_session_id, incoming.web_session_id));
const live = rows.filter(r => !/^MERGED/i.test(String(r.lead_status || '')) && isMatch(r))
  .sort((a, b) => String(a.created_at || '').localeCompare(String(b.created_at || '')));   // oldest first

const primary = live[0] || null;          // the oldest profile survives
const duplicates = live.slice(1);         // any other rows for the same person get merged into it

let matchedBy = 'none';
if (primary) {
  if (incoming.email && normEmail(primary.email) === incoming.email) matchedBy = 'email';
  else if (normPhone(incoming.phone) && normPhone(primary.phone) === normPhone(incoming.phone)) matchedBy = 'phone';
  else if (incoming.discord_id && same(primary.discord_id, incoming.discord_id)) matchedBy = 'discord_id';
  else matchedBy = 'web_session';
  if (duplicates.length) matchedBy += ' (+' + duplicates.length + ' duplicate merged)';
}

const now = new Date().toISOString();
const base = primary ? { ...primary } : {
  customer_id: 'HRE-' + Date.now().toString(36).toUpperCase(),
  name: '', email: '', phone: '', discord_id: '', web_session_id: '',
  channels_used: '', first_channel: msg.channel, last_channel: msg.channel,
  transaction_type: '', property_type: '', budget: '', preferred_neighborhoods: '', bedrooms: '',
  timeline: '', financing_status: '', lead_status: 'New', lead_score: 0,
  interested_listings: '', assigned_broker: '', conversation_summary: '',
  created_at: now, last_contact: now
};

// ---- merge each duplicate into the surviving profile (fill blanks only, combine lists) ----
const blank = v => String(v === undefined || v === null ? '' : v).trim() === '';
const fillFields = ['name','email','phone','discord_id','web_session_id','transaction_type','property_type','budget',
  'preferred_neighborhoods','bedrooms','timeline','financing_status','assigned_broker','conversation_summary'];
const channels = new Set(String(base.channels_used || '').split(',').map(s => s.trim()).filter(Boolean));
const listings = new Set(String(base.interested_listings || '').split(',').map(s => s.trim()).filter(Boolean));
for (const d of duplicates) {
  for (const f of fillFields) if (blank(base[f]) && !blank(d[f])) base[f] = d[f];
  String(d.channels_used || '').split(',').map(s => s.trim()).filter(Boolean).forEach(c => channels.add(c));
  String(d.interested_listings || '').split(',').map(s => s.trim()).filter(Boolean).forEach(l => listings.add(l));
  base.lead_score = Math.max(Number(base.lead_score) || 0, Number(d.lead_score) || 0);
  if (/^Hot/i.test(String(d.lead_status || '')) && !/^Hot/i.test(String(base.lead_status || ''))) base.lead_status = d.lead_status;
}
base.interested_listings = [...listings].join(', ');

// ---- fill gaps from the incoming message (never overwrite data already on file) ----
if (blank(base.name) && msg.name) base.name = msg.name;
if (blank(base.email) && incoming.email) base.email = incoming.email;
if (blank(base.phone) && incoming.phone) base.phone = incoming.phone;
if (blank(base.discord_id) && incoming.discord_id) base.discord_id = incoming.discord_id;
if (blank(base.web_session_id) && incoming.web_session_id) base.web_session_id = incoming.web_session_id;

channels.add(msg.channel);
base.channels_used = [...channels].join(', ');
base.last_channel = msg.channel;
base.last_contact = now;

return [{ json: {
  customer: base,
  is_new: !primary,
  matched_by: matchedBy,
  message: msg,
  duplicates: duplicates.map(d => ({ customer_id: d.customer_id, merged_into: base.customer_id }))
} }];

// Runs AFTER the surviving profile has been saved. One item per duplicate row that must be deleted (zero items = nothing to do).
const d = $('Resolve Identity').first().json.duplicates || [];
return d.map(x => ({ json: x }));
